import { AspectRatio } from '@/components/ui/aspect-ratio';

function dummyImage(width: number, height: number, label: string) {
  return `https://placehold.co/${width}x${height}?text=${encodeURIComponent(label)}`;
}

export function AspectRatioDemo() {
  return (
    <div className="min-w-[400px] p-4">
      <AspectRatio ratio={16 / 9}>
        <img
          src={dummyImage(640, 360, '16:9')}
          alt="Example constrained to 16:9"
          className="h-full w-full rounded-md object-cover"
        />
      </AspectRatio>
    </div>
  );
}

import { AspectRatio } from '@/components/ui/aspect-ratio';

function dummyImage(width: number, height: number, label: string) {
  return `https://placehold.co/${width}x${height}?text=${encodeURIComponent(label)}`;
}

function RatioTile({
  ratio,
  ratioLabel,
  orientationLabel,
  width,
  height,
  className,
}: Readonly<{
  ratio: number;
  ratioLabel: string;
  orientationLabel: string;
  width: number;
  height: number;
  className?: string;
}>) {
  return (
    <div className={className}>
      <AspectRatio ratio={ratio}>
        <img
          src={dummyImage(width, height, ratioLabel)}
          alt={`${ratioLabel} ${orientationLabel} placeholder`}
          className="h-full w-full rounded-md object-cover"
        />
      </AspectRatio>
    </div>
  );
}

export function AspectRatioLandscapeRatios() {
  const tiles: {
    ratio: number;
    ratioLabel: string;
    width: number;
    height: number;
  }[] = [
    {
      ratio: 1,
      ratioLabel: '1:1',
      width: 500,
      height: 500,
    },
    {
      ratio: 5 / 4,
      ratioLabel: '5:4',
      width: 500,
      height: 400,
    },
    {
      ratio: 4 / 3,
      ratioLabel: '4:3',
      width: 400,
      height: 300,
    },
    {
      ratio: 3 / 2,
      ratioLabel: '3:2',
      width: 600,
      height: 400,
    },
    {
      ratio: 16 / 9,
      ratioLabel: '16:9',
      width: 640,
      height: 360,
    },
    {
      ratio: 2,
      ratioLabel: '2:1',
      width: 600,
      height: 300,
    },
  ];
  return (
    <div className="grid max-w-5xl min-w-[400px] grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-6">
      {tiles.map(tile => (
        <RatioTile
          key={tile.ratioLabel}
          ratio={tile.ratio}
          ratioLabel={tile.ratioLabel}
          orientationLabel="Landscape"
          width={tile.width}
          height={tile.height}
          className="size-[100px]"
        />
      ))}
    </div>
  );
}

