import { zodResolver } from '@hookform/resolvers/zod';
import { format, isValid, parse } from 'date-fns';
import * as React from 'react';
import { Controller, useForm as useRhfForm } from 'react-hook-form';
import * as z from 'zod';
import { Button } from '@/components/ui/button';
import { Calendar } from '@/components/ui/calendar';
import { Checkbox } from '@/components/ui/checkbox';
import {
  DropdownMenu,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  Field,
  FieldDescription,
  FieldError,
  FieldLabel,
} from '@/components/ui/field';
import { Icon } from '@/components/ui/icon';
import { IconShell } from '@/components/ui/icon-shell';
import { Input } from '@/components/ui/input';
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from '@/components/ui/input-group';
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover';
import { Textarea } from '@/components/ui/textarea';
import { TimeInput } from '@/components/ui/time-input';
import { TimePickerListContent } from '@/components/ui/time-picker';
import { cn } from '@/lib/utils';
import { dateInputClassName } from './date-picker';
import { TimePickerColumn, sampleHours, sampleMinutes } from './time-picker';

const formSchema = z.object({
  field1: z.string().min(1, 'This field is required.'),
  field2: z.string().min(1, 'This field is required.'),
  date: z.string().min(1, 'Date is required.'),
  time: z.string().min(1, 'Time is required.'),
  bio: z.string().min(1, 'Required.').max(150, 'Max 150 characters.'),
  acceptTerms: z.boolean().refine(val => val === true, {
    message: 'You must accept the terms.',
  }),
  newsletter: z.boolean(),
});

type FormValues = z.infer<typeof formSchema>;

const defaultValues: FormValues = {
  field1: '',
  field2: '',
  date: '',
  time: '',
  bio: '',
  acceptTerms: true,
  newsletter: false,
};

const formFieldInlineLabel = cn(
  'label-regular-primary text-fg-secondary',
  'mb-[-4px]',
);

const datePickerInlineLabel = cn('label-regular-primary', 'mb-[-4px]');

function FormDemoContainer(props: Readonly<React.ComponentProps<'div'>>) {
  const { className, ...rest } = props;
  return (
    <div
      className={cn(
        'flex w-full max-w-[420px] min-w-[320px] flex-col gap-8 py-4',
        className,
      )}
      {...rest}
    />
  );
}

function FormDemoForm(props: Readonly<React.ComponentProps<'form'>>) {
  const { className, ...rest } = props;
  return (
    <form
      className={cn('flex w-[420px] flex-col gap-8', className)}
      {...rest}
    />
  );
}

function FormShellHeader() {
  return (
    <div className="flex flex-col gap-4">
      <h2 className="headings-h2-regular text-fg-primary">
        {'Form Title Goes Here'}
      </h2>
      <p className="paragraph-large-primary text-fg-secondary">
        {
          'Fill in the fields below so we can verify your details and provide the most relevant results. Please ensure all information is accurate to avoid any processing delays.'
        }
      </p>
    </div>
  );
}

function FormShellFooter({
  formId,
  onReset,
}: Readonly<{
  formId: string;
  onReset: () => void;
}>) {
  return (
    <div className="flex gap-2">
      <Button type="submit" form={formId}>
        {'Submit'}
      </Button>
      <Button type="button" variant="outline" onClick={onReset}>
        {'Cancel'}
      </Button>
    </div>
