}

function FormBioCharCount({
  current,
  max,
}: Readonly<{
  current: number;
  max: number;
}>) {
  const over = current > max;
  return (
    <div className="text-fg-secondary ml-auto flex items-center gap-0.5">
      <span
        className={cn(
          current > 0 && !over && 'text-fg-primary',
          over && 'text-status-error',
        )}>
        {current}
      </span>
      <span>/</span>
      <span>{max}</span>
    </div>
  );
}

function parseTimeFieldString(value: string | undefined) {
  if (!value) {
    return {
      hour: null as number | null,
      minute: null as number | null,
    };
  }
  const [h, m] = value.split(':');
  const hour = h ? Number.parseInt(h, 10) : null;
  const minute = m ? Number.parseInt(m, 10) : null;
  return {
    hour: Number.isFinite(hour) ? hour : null,
    minute: Number.isFinite(minute) ? minute : null,
  };
}

function formatTimeFieldValue(hour: number | null, minute: number | null) {
  if (hour === null && minute === null) {
    return '';
  }
  const hh = String(hour ?? 0).padStart(2, '0');
  const mm = String(minute ?? 0).padStart(2, '0');
  return `${hh}:${mm}`;
}

function useDatePickerField(value: string) {
  const [open, setOpen] = React.useState(false);
  const [month, setMonth] = React.useState<Date | undefined>(undefined);
  const parsedDate = value ? parse(value, 'yyyy-MM-dd', new Date()) : undefined;
  const selectedDate =
    parsedDate && isValid(parsedDate) ? parsedDate : undefined;
  const syncMonthFromValue = React.useCallback((raw: string) => {
    if (!raw) {
      return;
    }
    const parsed = parse(raw, 'yyyy-MM-dd', new Date());
    if (isValid(parsed)) {
      setMonth(parsed);
    }
  }, []);
  return {
    open,
    setOpen,
    month,
    setMonth,
    selectedDate,
    syncMonthFromValue,
  };
}

type CommonRowProps = {
  id: string;
  name: string;
  label: string;
  description?: string;
  errorMessage?: string;
  invalid: boolean;
};

type TextLikeRowProps = CommonRowProps & {
  placeholder?: string;
  value: string;
  onChange: (value: string) => void;
  onBlur?: () => void;
  variant?: 'default' | 'inline';
};

function TextFieldRow({
  id,
  name,
  label,
  description,
  errorMessage,
  invalid,
  placeholder,
  value,
  onChange,
  onBlur,
  variant = 'default',
}: Readonly<TextLikeRowProps>) {
  const labelClass =
    variant === 'inline'
      ? formFieldInlineLabel
      : 'label-regular-primary text-fg-secondary';
  return (
    <Field data-invalid={invalid} className="gap-2">
      <FieldLabel htmlFor={id} className={labelClass}>
        {label}
      </FieldLabel>
      <Input
        id={id}
        name={name}
        value={value}
        onChange={e => onChange(e.target.value)}
        onBlur={onBlur}
        variant={variant === 'inline' ? 'inline' : undefined}
        aria-invalid={invalid}
        placeholder={placeholder}
      />
      {errorMessage ? (
        <FieldError>{errorMessage}</FieldError>
      ) : description ? (
        <FieldDescription className="paragraph-regular-primary text-fg-tertiary">
          {description}
        </FieldDescription>
      ) : null}
    </Field>
  );
}

type DateRowProps = CommonRowProps & {
  value: string;
  onChange: (value: string) => void;
  onBlur?: () => void;
  variant?: 'default' | 'inline';
};

function DateFieldRow({
  id,
  name,
  label,
  description,
  errorMessage,
  invalid,
  value,
  onChange,
  onBlur,
  variant = 'default',
}: Readonly<DateRowProps>) {
  const labelClass =
    variant === 'inline' ? datePickerInlineLabel : 'label-regular-primary';
  const inputGroupVariant = variant === 'inline' ? 'inline' : undefined;
  const inputVariant = variant === 'inline' ? 'inline' : undefined;
  const { open, setOpen, month, setMonth, selectedDate, syncMonthFromValue } =
    useDatePickerField(value);
  const handleOpenChange = (next: boolean) => {
    setOpen(next);
    if (next) {
      syncMonthFromValue(value);
    }
  };
  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const next = e.target.value;
    onChange(next);
    syncMonthFromValue(next);
  };
  const handleCalendarSelect = (d: Date | undefined) => {
    onChange(d ? format(d, 'yyyy-MM-dd') : '');
    if (d) {
      setMonth(d);
    }
    setOpen(false);
  };
  return (
    <Field data-invalid={invalid} className={cn('min-w-0 gap-2')}>
      <FieldLabel htmlFor={id} className={labelClass}>
        {label}
      </FieldLabel>
      <Popover open={open} onOpenChange={handleOpenChange}>
        <PopoverTrigger asChild>
          <InputGroup
            variant={inputGroupVariant}
            data-open={open}
            className="cursor-pointer">
            <InputGroupInput
              id={id}
              name={name}
              type="date"
              variant={inputVariant}
              value={value}
              onChange={handleInputChange}
              onBlur={onBlur}
              data-empty={value ? 'false' : 'true'}
              className={dateInputClassName}
              aria-invalid={invalid}
              aria-label={label}
            />
            <InputGroupAddon align="inline-end">
              <span className="flex size-5 cursor-pointer items-center justify-center">
                <IconShell size="sm">
                  <Icon
                    icon="calendar_month"
                    className="text-[length:inherit]"
                  />
                </IconShell>
              </span>
            </InputGroupAddon>
          </InputGroup>
        </PopoverTrigger>
        <PopoverContent
          className="w-auto overflow-hidden border-none p-0"
          align="start"
          sideOffset={4}
          onOpenAutoFocus={e => e.preventDefault()}>
          <Calendar
            mode="single"
            size="default"
            month={month}
            onMonthChange={setMonth}
            selected={selectedDate}
            onSelect={handleCalendarSelect}
          />
        </PopoverContent>
      </Popover>
      {errorMessage ? (
        <FieldError>{errorMessage}</FieldError>
      ) : description ? (
        <FieldDescription>{description}</FieldDescription>
      ) : null}
    </Field>
  );
}

type TimeRowProps = CommonRowProps & {
  value: string;
  onChange: (value: string) => void;
  onBlur?: () => void;
  variant?: 'default' | 'inline';
};

function TimeFieldRow({
  id,
  name,
  label,
  description,
  errorMessage,
  invalid,
  value,
  onChange,
  onBlur,
  variant = 'default',
}: Readonly<TimeRowProps>) {
  const labelClass =
    variant === 'inline'
      ? formFieldInlineLabel
      : 'label-regular-primary text-fg-secondary';
  const { hour, minute } = parseTimeFieldString(value);
  const [open, setOpen] = React.useState(false);
  return (
    <Field data-invalid={invalid} className="gap-2">
      <FieldLabel htmlFor={id} className={labelClass}>
        {label}
      </FieldLabel>
      <DropdownMenu open={open} onOpenChange={setOpen} modal={false}>
        <DropdownMenuTrigger asChild>
          <TimeInput
            id={id}
            name={name}
            hour={hour}
            minute={minute}
            onHourChange={h => onChange(formatTimeFieldValue(h, minute))}
            onMinuteChange={m => onChange(formatTimeFieldValue(hour, m))}
            onBlur={onBlur}
            aria-invalid={invalid}
            data-open={open}
            variant={variant === 'inline' ? 'inline' : 'default'}
            className={
              variant === 'inline' ? undefined : 'w-fit justify-between'
            }
          />
        </DropdownMenuTrigger>
        <TimePickerListContent
          size="default"
          className="z-10"
          sideOffset={4}
          align="start"
          onOpenAutoFocus={e => e.preventDefault()}
          onInteractOutside={e => {
            const custom = e as CustomEvent<{
              originalEvent: PointerEvent;
            }>;
            const target = custom.detail?.originalEvent?.target;
            if (
              target instanceof HTMLElement &&
              target.closest('[data-slot="time-input-root"]')
            ) {
              e.preventDefault();
            }
          }}>
          <TimePickerColumn
            value={hour}
            onValueChange={h => onChange(formatTimeFieldValue(h, minute))}
            items={sampleHours}
            size="default"
          />
          <TimePickerColumn
            value={minute}
            onValueChange={m => onChange(formatTimeFieldValue(hour, m))}
            items={sampleMinutes}
            size="default"
          />
        </TimePickerListContent>
      </DropdownMenu>
      {errorMessage ? (
        <FieldError>{errorMessage}</FieldError>
      ) : description ? (
        <FieldDescription className="paragraph-regular-primary text-fg-tertiary">
          {description}
        </FieldDescription>
      ) : null}
    </Field>
  );
}

type TextareaRowProps = CommonRowProps & {
  placeholder?: string;
  value: string;
  onChange: (value: string) => void;
  onBlur?: () => void;
  maxChars: number;
};

function TextareaFieldRow({
  id,
  name,
  label,
  description,
  errorMessage,
  invalid,
  placeholder,
  value,
  onChange,
  onBlur,
  maxChars,
}: Readonly<TextareaRowProps>) {
  const length = value?.length ?? 0;
  const overMax = length > maxChars;
  const effectiveInvalid = invalid || overMax;
  const overflowMessage =
    !errorMessage && overMax ? `Max ${maxChars} characters.` : undefined;
  const displayedMessage = errorMessage ?? overflowMessage;
  return (
    <Field data-invalid={effectiveInvalid} className="gap-2">
      <div className="flex flex-col gap-2">
        <FieldLabel
          htmlFor={id}
          className={cn(
            'label-regular-primary text-fg-secondary',
            'flex w-full items-center justify-between',
          )}>
          {label}
          <FormBioCharCount current={length} max={maxChars} />
        </FieldLabel>
        <Textarea
          id={id}
          name={name}
          value={value}
          onChange={e => onChange(e.target.value)}
          onBlur={onBlur}
          aria-invalid={effectiveInvalid}
          placeholder={placeholder}
          rows={4}
        />
      </div>
      {displayedMessage ? (
        <FieldError>{displayedMessage}</FieldError>
      ) : description ? (
        <FieldDescription className="paragraph-regular-primary text-fg-tertiary">
          {description}
        </FieldDescription>
      ) : null}
    </Field>
  );
}

type CheckboxRowProps = {
  id: string;
  name: string;
  label: string;
  errorMessage?: string;
  invalid?: boolean;
  checked: boolean;
  onChange: (checked: boolean) => void;
};

function CheckboxFieldRow({
  id,
  name,
  label,
  errorMessage,
  invalid,
  checked,
  onChange,
