      <span>/</span>
      <span>{max}</span>
    </div>
  );
}

type TanStackFieldErrors = ReadonlyArray<
  | string
  | {
      message?: string;
    }
  | null
  | undefined
>;

type NormalizedFieldError = {
  message?: string;
};

function normalizeTanStackErrors(
  errors: TanStackFieldErrors,
): NormalizedFieldError[] {
  return errors
    .filter(
      (
        e,
      ): e is
        | string
        | {
            message?: string;
          } => Boolean(e),
    )
    .map(e =>
      typeof e === 'string'
        ? {
            message: e,
          }
        : e,
    );
}

function getTanStackFieldStatus(meta: {
  isTouched: boolean;
  isValid: boolean;
  errors: TanStackFieldErrors;
}): {
  isInvalid: boolean;
  errors: NormalizedFieldError[];
} {
  const isInvalid = meta.isTouched && !meta.isValid;
  return {
    isInvalid,
    errors: normalizeTanStackErrors(meta.errors),
  };
}

function parseTimeFieldString(value: string | undefined) {
  if (!value) {
    return {
      hour: null as number | null,
      minute: null as number | null,
    };
  }
  const [h, m] = value.split(':');
  const hour = h ? Number.parseInt(h, 10) : null;
  const minute = m ? Number.parseInt(m, 10) : null;
  return {
    hour: Number.isFinite(hour) ? hour : null,
    minute: Number.isFinite(minute) ? minute : null,
  };
}

function formatTimeFieldValue(hour: number | null, minute: number | null) {
  if (hour === null && minute === null) {
    return '';
  }
  const hh = String(hour ?? 0).padStart(2, '0');
  const mm = String(minute ?? 0).padStart(2, '0');
  return `${hh}:${mm}`;
}

function useDatePickerField(value: string) {
  const [open, setOpen] = React.useState(false);
  const [month, setMonth] = React.useState<Date | undefined>(undefined);
  const parsedDate = value ? parse(value, 'yyyy-MM-dd', new Date()) : undefined;
  const selectedDate =
    parsedDate && isValid(parsedDate) ? parsedDate : undefined;
  const syncMonthFromValue = React.useCallback((raw: string) => {
    if (!raw) {
      return;
    }
    const parsed = parse(raw, 'yyyy-MM-dd', new Date());
    if (isValid(parsed)) {
      setMonth(parsed);
    }
  }, []);
  return {
    open,
    setOpen,
    month,
    setMonth,
    selectedDate,
    syncMonthFromValue,
  };
}

type CommonRowProps = {
  id: string;
  name: string;
  label: string;
  description?: string;
  errorMessage?: string;
  invalid: boolean;
};

type TextLikeRowProps = CommonRowProps & {
  placeholder?: string;
  value: string;
  onChange: (value: string) => void;
  onBlur?: () => void;
  variant?: 'default' | 'inline';
};

function TextFieldRow({
  id,
  name,
  label,
  description,
  errorMessage,
  invalid,
  placeholder,
  value,
  onChange,
  onBlur,
  variant = 'default',
}: Readonly<TextLikeRowProps>) {
