        onBlur={onBlur}
        variant={variant === 'inline' ? 'inline' : undefined}
        aria-invalid={invalid}
        placeholder={placeholder}
      />
      {errorMessage ? (
        <FieldError>{errorMessage}</FieldError>
      ) : description ? (
        <FieldDescription className="paragraph-regular-primary text-fg-tertiary">
