      : 'label-regular-primary text-fg-secondary';
  const { hour, minute } = parseTimeFieldString(value);
  const [open, setOpen] = React.useState(false);
  return (
    <Field data-invalid={invalid} className="gap-2">
      <FieldLabel htmlFor={id} className={labelClass}>
        {label}
      </FieldLabel>
      <DropdownMenu open={open} onOpenChange={setOpen} modal={false}>
        <DropdownMenuTrigger asChild>
          <TimeInput
            id={id}
            name={name}
            hour={hour}
            minute={minute}
            onHourChange={h => onChange(formatTimeFieldValue(h, minute))}
            onMinuteChange={m => onChange(formatTimeFieldValue(hour, m))}
            onBlur={onBlur}
            aria-invalid={invalid}
            data-open={open}
            variant={variant === 'inline' ? 'inline' : 'default'}
            className={
              variant === 'inline' ? undefined : 'w-fit justify-between'
            }
          />
        </DropdownMenuTrigger>
        <TimePickerListContent
          size="default"
          className="z-10"
          sideOffset={4}
          align="start"
          onOpenAutoFocus={e => e.preventDefault()}
          onInteractOutside={e => {
            const custom = e as CustomEvent<{
              originalEvent: PointerEvent;
            }>;
            const target = custom.detail?.originalEvent?.target;
            if (
              target instanceof HTMLElement &&
              target.closest('[data-slot="time-input-root"]')
            ) {
              e.preventDefault();
            }
          }}>
          <TimePickerColumn
            value={hour}
            onValueChange={h => onChange(formatTimeFieldValue(h, minute))}
            items={sampleHours}
            size="default"
          />
          <TimePickerColumn
            value={minute}
            onValueChange={m => onChange(formatTimeFieldValue(hour, m))}
            items={sampleMinutes}
            size="default"
          />
        </TimePickerListContent>
      </DropdownMenu>
      {errorMessage ? (
        <FieldError>{errorMessage}</FieldError>
      ) : description ? (
        <FieldDescription className="paragraph-regular-primary text-fg-tertiary">
          {description}
        </FieldDescription>
      ) : null}
    </Field>
  );
}

type TextareaRowProps = CommonRowProps & {
  placeholder?: string;
  value: string;
  onChange: (value: string) => void;
  onBlur?: () => void;
  maxChars: number;
};

function TextareaFieldRow({
  id,
  name,
  label,
  description,
  errorMessage,
  invalid,
  placeholder,
  value,
  onChange,
  onBlur,
  maxChars,
}: Readonly<TextareaRowProps>) {
  const length = value?.length ?? 0;
  const overMax = length > maxChars;
  const effectiveInvalid = invalid || overMax;
  const overflowMessage =
    !errorMessage && overMax ? `Max ${maxChars} characters.` : undefined;
  const displayedMessage = errorMessage ?? overflowMessage;
  return (
    <Field data-invalid={effectiveInvalid} className="gap-2">
      <div className="flex flex-col gap-2">
        <FieldLabel
          htmlFor={id}
          className={cn(
            'label-regular-primary text-fg-secondary',
            'flex w-full items-center justify-between',
          )}>
          {label}
          <FormBioCharCount current={length} max={maxChars} />
        </FieldLabel>
        <Textarea
          id={id}
          name={name}
          value={value}
          onChange={e => onChange(e.target.value)}
          onBlur={onBlur}
          aria-invalid={effectiveInvalid}
          placeholder={placeholder}
          rows={4}
        />
      </div>
      {displayedMessage ? (
        <FieldError>{displayedMessage}</FieldError>
      ) : description ? (
        <FieldDescription className="paragraph-regular-primary text-fg-tertiary">
          {description}
        </FieldDescription>
      ) : null}
    </Field>
  );
}

