import { useState } from 'react';
import { FieldDescription, FieldSet, FieldTitle } from '@/components/ui/field';
import { Icon } from '@/components/ui/icon';
import { IconShell } from '@/components/ui/icon-shell';
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from '@/components/ui/input-group';
import { cn } from '@/lib/utils';
import { inputGroupFieldConfig } from './input-group-config';

export function InputGroupStepperSizes() {
  const sizes = [
    {
      label: 'Small',
      size: 'sm' as const,
      width: 'w-[160px]',
    },
    {
      label: 'Default',
      size: 'default' as const,
      width: 'w-[160px]',
    },
    {
      label: 'Large',
      size: 'lg' as const,
      width: 'w-[160px]',
    },
  ];
  function StepperItem({
    size,
    width,
    variant,
  }: Readonly<{
    size: 'sm' | 'default' | 'lg';
    width: string;
    variant: 'default' | 'inline';
  }>) {
    const { label: labelClass, description, gap } = inputGroupFieldConfig[size];
    const labelClassName = cn(
      labelClass,
      variant === 'inline' &&
        (size === 'default' || size === 'lg') &&
        'mb-[-4px]',
    );
    const [value, setValue] = useState(0);
    const increment = () => {
      setValue(prev => prev + 1);
    };
    const decrement = () => {
      setValue(prev => Math.max(0, prev - 1));
    };
    const buttonSize = size === 'lg' ? 'icon-xs' : 'icon-xxs';
    const iconShellSize = size === 'lg' ? 'default' : 'sm';
    const isDecrementDisabled = value === 0;
    return (
      <FieldSet className={`${width} ${gap}`}>
        <FieldTitle className={labelClassName}>Label</FieldTitle>
        <InputGroup variant={variant} size={size} className={width}>
          <InputGroupAddon align="inline-start">
            <InputGroupButton
              size={buttonSize}
              variant="ghost"
              onClick={decrement}
              disabled={isDecrementDisabled}
              aria-label="Decrease">
              <IconShell
                size={iconShellSize}
                type="neutral"
                variant="secondary"
                disabled={isDecrementDisabled}>
                <Icon icon="remove" />
              </IconShell>
            </InputGroupButton>
          </InputGroupAddon>
          <InputGroupInput
            type="number"
            variant={variant}
            size={size}
            value={value}
            onChange={e => setValue(Number(e.target.value) || 0)}
            min={0}
            className="text-center"
          />
          <InputGroupAddon align="inline-end">
            <InputGroupButton
              size={buttonSize}
              variant="ghost"
              onClick={increment}
              aria-label="Increase">
              <IconShell size={iconShellSize} type="neutral" hoverable>
                <Icon icon="add" />
              </IconShell>
            </InputGroupButton>
          </InputGroupAddon>
        </InputGroup>
