import { useState } from 'react';
import { FieldDescription, FieldSet, FieldTitle } from '@/components/ui/field';
import { Icon } from '@/components/ui/icon';
import { IconShell } from '@/components/ui/icon-shell';
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from '@/components/ui/input-group';
import { cn } from '@/lib/utils';

export function InputGroupStepperStates() {
  const stepperStates = [
    {
      label: 'Error',
      status: 'error' as const,
      statusMessage: 'Feedback here',
      statusClass: 'text-status-error',
      defaultInputGroupClass: '',
      inlineInputGroupClass:
        'has-[[data-slot][aria-invalid=true]]:!border-b has-[[data-slot][aria-invalid=true]]:!border-b-status-error',
    },
    {
      label: 'Warning',
      status: 'warning' as const,
      statusMessage: 'Feedback here',
      statusClass: 'text-status-warning',
      defaultInputGroupClass: '!border !border-status-warning',
      inlineInputGroupClass: '!border-b !border-b-status-warning',
    },
    {
      label: 'Success',
      status: 'success' as const,
      statusMessage: 'Feedback here',
      statusClass: 'text-status-success',
      defaultInputGroupClass: '!border !border-status-success',
      inlineInputGroupClass: '!border-b !border-b-status-success',
    },
  ];
  function StepperStateItem({
    status,
    statusMessage,
    statusClass,
    variant,
    inputGroupClass,
  }: Readonly<{
    status: 'error' | 'warning' | 'success';
    statusMessage: string;
    statusClass: string;
    variant: 'default' | 'inline';
    inputGroupClass: string;
  }>) {
    const [value, setValue] = useState(234);
    const increment = () => {
      setValue(prev => prev + 1);
    };
    const decrement = () => {
      setValue(prev => Math.max(0, prev - 1));
    };
    const isDecrementDisabled = value === 0;
    const stateLabelClassName = cn(
      'label-regular-primary text-fg-secondary',
      variant === 'inline' && 'mb-[-4px]',
    );
    return (
      <FieldSet className="w-[160px] gap-2">
        <FieldTitle className={stateLabelClassName}>Label</FieldTitle>
        <InputGroup
          variant={variant}
          size="default"
          className={cn('w-[160px]', inputGroupClass)}>
          <InputGroupAddon align="inline-start">
            <InputGroupButton
              size="icon-xxs"
              variant="ghost"
              onClick={decrement}
              disabled={isDecrementDisabled}
              aria-label="Decrease">
              <IconShell size="sm" hoverable disabled={isDecrementDisabled}>
                <Icon icon="remove" />
              </IconShell>
            </InputGroupButton>
          </InputGroupAddon>
          <InputGroupInput
            type="number"
            variant={variant}
            size="default"
            value={value}
            onChange={e => setValue(Number(e.target.value) || 0)}
            min={0}
            className="text-center"
            aria-invalid={status === 'error' ? true : undefined}
          />
          <InputGroupAddon align="inline-end">
            <InputGroupButton
              size="icon-xxs"
              variant="ghost"
              onClick={increment}
              aria-label="Increase">
              <IconShell size="sm" hoverable>
                <Icon icon="add" />
              </IconShell>
            </InputGroupButton>
          </InputGroupAddon>
        </InputGroup>
        <FieldDescription
          className={`paragraph-regular-primary text-fg-tertiary ${statusClass}`}>
          {statusMessage}
        </FieldDescription>
      </FieldSet>
    );
  }
  return (
    <div className="w-full space-y-6">
      {stepperStates.map(
        ({
          status,
          statusMessage,
          statusClass,
          defaultInputGroupClass,
          inlineInputGroupClass,
        }) => (
          <div key={status} className="flex justify-center gap-[200px]">
            <StepperStateItem
              status={status}
              statusMessage={statusMessage}
              statusClass={statusClass}
              variant="default"
              inputGroupClass={defaultInputGroupClass}
            />

            <StepperStateItem
              status={status}
              statusMessage={statusMessage}
              statusClass={statusClass}
              variant="inline"
              inputGroupClass={inlineInputGroupClass}
            />
          </div>
        ),
      )}
    </div>
  );
}

import { useRef, useState } from 'react';
import { FieldDescription, FieldSet, FieldTitle } from '@/components/ui/field';
import { Icon } from '@/components/ui/icon';
import { IconShell } from '@/components/ui/icon-shell';
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
  InputGroupText,
} from '@/components/ui/input-group';
import { cn } from '@/lib/utils';

export function InputGroupDeleteOnFocus() {
  const inlineLabelClass = cn(
    'label-regular-primary text-fg-secondary',
    'mb-[-4px]',
  );
  function DeleteOnFocusField({
    variant,
    labelClassName,
  }: Readonly<{
    variant: 'default' | 'inline';
    labelClassName: string;
  }>) {
    const [value, setValue] = useState('');
    const groupContainerRef = useRef<HTMLDivElement>(null);
    const focusControl = () => {
      const control =
        groupContainerRef.current?.querySelector<HTMLInputElement>(
          '[data-slot=input-group-control]',
        );
      control?.focus();
    };
    const deleteAddonVisibility = cn(
      'transition-[opacity,visibility] duration-150',
      'invisible opacity-0 pointer-events-none',
      'group-focus-within:visible group-focus-within:opacity-100 group-focus-within:pointer-events-auto',
    );
    return (
      <FieldSet className="w-[240px] gap-2">
        <FieldTitle className={labelClassName}>Label</FieldTitle>
        <div ref={groupContainerRef} className="group">
          <InputGroup variant={variant}>
            <InputGroupAddon align="inline-start">
              <InputGroupText>
                <IconShell
                  size="sm"
                  type="neutral"
                  variant="secondary"
                  aria-hidden>
                  <Icon icon="search" />
                </IconShell>
              </InputGroupText>
            </InputGroupAddon>
            <InputGroupInput
              variant={variant}
              placeholder="Search…"
              value={value}
              autoComplete="off"
              onChange={e => setValue(e.target.value)}
            />
            <InputGroupAddon
              align="inline-end"
              className={deleteAddonVisibility}>
              <InputGroupButton
                type="button"
                size="icon-xs"
                variant="ghost"
                aria-label="Delete entered text"
                className="hover:bg-transparent active:bg-transparent"
                onClick={() => {
                  setValue('');
                  focusControl();
                }}>
                <IconShell size="sm" type="neutral" hoverable>
                  <Icon icon="backspace" />
                </IconShell>
              </InputGroupButton>
            </InputGroupAddon>
          </InputGroup>
        </div>
        <FieldDescription className="paragraph-regular-primary text-fg-tertiary">
          Helper text
        </FieldDescription>
      </FieldSet>
    );
  }
  return (
    <div className="flex flex-col gap-6">
      <DeleteOnFocusField
        variant="default"
        labelClassName="label-regular-primary text-fg-secondary"
      />
      <DeleteOnFocusField variant="inline" labelClassName={inlineLabelClass} />
    </div>
  );
}

