export function TableRich() {
  const [selectedRows, setSelectedRows] = useState<number[]>([]);
  const toggleRow = (id: number) => {
    setSelectedRows(prev =>
      prev.includes(id) ? prev.filter(rowId => rowId !== id) : [...prev, id],
    );
  };
  return (
    <Table>
      <TableHeader>
        <TableRow>
          <TableHead className="w-[50px]" />
          <TableHead>User</TableHead>
          <TableHead>Role</TableHead>
          <TableHead>Status</TableHead>
          <TableHead className="text-right">Actions</TableHead>
        </TableRow>
      </TableHeader>
      <TableBody>
        {users.map(user => (
          <TableRow
            key={user.id}
            data-state={
              selectedRows.includes(user.id) ? 'selected' : undefined
            }>
            <TableCell>
              <Checkbox
                checked={selectedRows.includes(user.id)}
                onCheckedChange={() => toggleRow(user.id)}
              />
            </TableCell>
            <TableCell>
              <div className="flex items-center gap-3">
                <div className="relative">
                  <Avatar size="sm">
                    {user.avatar && <AvatarImage src={user.avatar} />}
                    <AvatarFallback>
                      {user.name
                        .split(' ')
                        .map(n => n[0])
                        .join('')}
                    </AvatarFallback>
                  </Avatar>
                  <StatusBadge
                    variant={user.status}
                    size="sm"
                    className="absolute -right-0.5 -bottom-0.5"
                  />
                </div>
                <div className="flex flex-col">
                  <span className="font-medium">{user.name}</span>
                  <span className="text-fg-secondary text-sm">
                    {user.email}
                  </span>
                </div>
              </div>
            </TableCell>
            <TableCell>
              <Badge variant="high-emphasis">{user.role}</Badge>
            </TableCell>
            <TableCell>
              <Badge outline variant="high-emphasis">
                {getUserStatusLabel(user.status)}
              </Badge>
            </TableCell>
            <TableCell className="text-right">
              <div className="flex items-center justify-end gap-1">
                <Button variant="ghost" size="icon-xxs" aria-label="Edit row">
                  <IconShell size="sm">
                    <Icon icon="edit" />
                  </IconShell>
                </Button>
                <Button variant="ghost" size="icon-xxs" aria-label="Delete row">
                  <IconShell size="sm">
                    <Icon icon="delete" />
                  </IconShell>
                </Button>
              </div>
