  value: number | null;
  onValueChange: (value: number) => void;
  items: number[];
  size: 'default' | 'lg';
}>) {
  const listRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const checked = listRef.current?.querySelector<HTMLElement>(
      '[data-state="checked"]',
    );
    if (checked) {
      checked.scrollIntoView({
        block: 'nearest',
      });
    }
